-- US-04c Pièces justificatives du KYC : une ligne par pièce déposée (au plus une par type
-- et par utilisateur) ; le fichier est dans R2 sous la clé "cle" (kyc/<utilisateur>/<type>).
CREATE TYPE "public"."statut_piece_kyc" AS ENUM('deposee', 'en_verification', 'validee', 'refusee');--> statement-breakpoint
CREATE TYPE "public"."type_piece_kyc" AS ENUM('identite', 'identite_verso', 'titre_sejour', 'domicile', 'rib', 'origine_fonds', 'ppe');--> statement-breakpoint
CREATE TABLE "kyc_piece" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "kyc_piece_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"utilisateur_id" text NOT NULL,
	"type" "type_piece_kyc" NOT NULL,
	"nom_fichier" text NOT NULL,
	"format" text NOT NULL,
	"taille" integer NOT NULL,
	"cle" text NOT NULL,
	"statut" "statut_piece_kyc" DEFAULT 'deposee' NOT NULL,
	"depose_le" timestamp with time zone DEFAULT now() NOT NULL,
	"modifie_le" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "kyc_piece_utilisateur_type_unique" UNIQUE("utilisateur_id","type")
);
